/// SplitMix風乱数生成機
pub struct SplitMix64 {
    state: u64,
} // end of struct SplitMix64

impl SplitMix64 {
    /// seedから乱数生成器を作成
    #[inline(always)]
    pub fn new(seed: u64) -> Self {
        return Self {
            state: seed,
        };
    } // end of constructor

    /// u64の疑似乱数を1つ返す
    #[inline(always)]
    pub fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0x9E3779B97F4A7C15_u64);

        let mut x = self.state;
        x = (x ^ (x >> 30)).wrapping_mul(0xBF58476D1CE4E5B9_u64);
        x = (x ^ (x >> 27)).wrapping_mul(0x94D049BB133111EB_u64);
        return x ^ (x >> 31);
    } // end of method
} // end of impl SplitMix64

/// Hash値で部分文字列の一致を判定
/// 範囲指定は 0-indexedの半開区間 [l, r)
/// modは2^61-1
/// u128を使って安全に積を計算
pub struct RollingHash {
    /// hash[i][j]はi番目の底で作ったs[0..j]のハッシュ値
    pub hash: Vec<Vec<u64>>,

    /// bases[i][j]はi番目の底のj乗
    pub bases: Vec<Vec<u64>>,

    /// ハッシュ対象のバイト列
    /// UTF-8文字列の場合は文字単位ではなくバイト列で, 競プロは1byte文字のみ想定
    pub bytes: Vec<u8>,

    /// 各バイトを数値化したもの
    /// 0を避けるためにbyte+1
    pub codes: Vec<u64>,

    /// バイト列の長さ
    pub n: usize,

    /// 底の個数
    /// 大きくするほど衝突率は下がるが計算量も定数倍に
    pub random_num: usize,
} // end of struct RollingHash

impl RollingHash {
    /// 2^61 - 1
    pub const MOD: u64 = (1_u64 << 61) - 1;

    pub fn new(s: &str, random_num: usize) -> Self {
        return Self::with_seed_from_str(s, random_num);
    } // end of constructor

    pub fn new_from_bytes(bytes: &[u8], random_num: usize) -> Self {
        return Self::with_seed_from_bytes(bytes, random_num, 0x0F1E2D3C4B5A6978_u64);
    } // end of method

    pub fn with_seed_from_str(s: &str, random_num: usize) -> Self {
        return Self::with_seed_from_bytes(s.as_bytes(), random_num, 0x0F1E2D3C4B5A6978_u64);
    } // end of constructor

    pub fn with_seed_from_bytes(bytes: &[u8], random_num: usize, seed: u64) -> Self {
        debug_assert!(random_num > 0);
        let n = bytes.len();

        let mut codes = vec![0_u64; n];
        for i in 0..n {
            codes[i] = bytes[i] as u64 + 1;
        }

        let mut hash = vec![vec![0_u64; n + 1]; random_num];
        let mut bases = vec![vec![0_u64; n + 1]; random_num];

        // 異なる長さの本文と検索語でも、同じseed・本数なら同じ基数を使う。
        let mixed_seed = seed ^ (random_num as u64);
        let mut rng = SplitMix64::new(mixed_seed);

        for i in 0..random_num {
            let base = Self::make_base(&mut rng);
            bases[i][0] = 1;

            for j in 1..=n {
                bases[i][j] = Self::mul_mod(base, bases[i][j - 1]);
                let value = Self::mul_mod(base, hash[i][j - 1]);
                hash[i][j] = Self::add_mod(value, codes[j - 1]);
            }
        }

        return Self {
            hash,
            bases,
            bytes: bytes.to_vec(),
            codes,
            n,
            random_num,
        };
    } // end of constructor

    /// [l, r)の部分文字列ハッシュ値を計算
    /// l, r は0-indexed
    #[inline(always)]
    pub fn calc_hashes(&self, l: usize, r: usize) -> Vec<u64> {
        debug_assert!(l <= r);
        debug_assert!(r <= self.n);

        let len = r - l;
        let mut result = Vec::with_capacity(self.random_num);

        for i in 0..self.random_num {
            // hash[i][r] → s[0..r]のハッシュ
            // hash[i][l] * base^len を引いてs[l..r]を取り出し
            let removed = Self::mul_mod(self.hash[i][l], self.bases[i][len]);
            let value = Self::sub_mod(self.hash[i][r], removed);
            result.push(value);
        }
        return result;
    } // end of method

    /// [l1, r1)と[l2, r2)が同じ文字列かをハッシュで比較
    /// 0-indexed
    #[inline(always)]
    pub fn compare_hash(&self, l1: usize, r1: usize, l2: usize, r2: usize) -> bool {
        debug_assert!(l1 <= r1);
        debug_assert!(r1 <= self.n);
        debug_assert!(l2 <= r2);
        debug_assert!(r2 <= self.n);

        let len1 = r1 - l1;
        let len2 = r2 - l2;
        // 長さが違えば一致しない
        if len1 != len2 {
            return false;
        }

        for i in 0..self.random_num {
            let removed1 = Self::mul_mod(self.hash[i][l1], self.bases[i][len1]);
            let value1 = Self::sub_mod(self.hash[i][r1], removed1);
            let removed2 = Self::mul_mod(self.hash[i][l2], self.bases[i][len2]);
            let value2 = Self::sub_mod(self.hash[i][r2], removed2);

            if value1 != value2 {
                return false;
            }
        }
        return true;
    } // end of method

    /// selfの文字列からtargetと一致する最初の位置を探す
    /// 同じseed・random_numで生成したRollingHash同士を渡す。
    ///
    /// self:
    ///     検索対象となる文字列SのRolling Hash
    ///
    /// target:
    ///     探したい文字列TのRolling Hash
    ///
    /// 戻り値:
    ///     見つかった場合は先頭位置
    ///     見つからなかった場合はNone
    ///
    /// 計算量: O((|S| - |T| + 1) * random_num)
    #[inline]
    pub fn find(&self, target: &RollingHash) -> Option<usize> {
        // 同じ個数の底を使用している必要がある
        debug_assert_eq!(self.random_num, target.random_num);
        if target.n == 0 {
            return Some(0);
        }
        if target.n > self.n {
            return None;
        }

        let target_len = target.n;

        // T全体のハッシュ値はprefix hashそのもの
        // target.hash[i][target.n]は、
        // i番目の底によるT全体のハッシュ値
        // これは検索ループの外で1回参照するだけでよく、
        // 各位置でTのハッシュを再計算する必要はない
        for left in 0..=(self.n - target_len) {
            let right = left + target_len;
            let mut matched = true;

            // 複数の底すべてについて一致するか
            for hash_index in 0..self.random_num {
                // S[left..right]のハッシュ値を取り出す
                let removed = Self::mul_mod(self.hash[hash_index][left], self.bases[hash_index][target_len]);
                let substring_hash = Self::sub_mod(self.hash[hash_index][right], removed);

                // T全体のハッシュ値
                let target_hash = target.hash[hash_index][target_len];

                // 1つでもハッシュが異なれば一致しない
                if substring_hash != target_hash {
                    matched = false;
                    break;
                }
            }

            if matched {
                // Rolling Hashには理論上ハッシュ衝突があるため、
                // 完全な一致判定が必要なら実際のバイト列も確認する
                // この比較が実行されるのはハッシュが一致した場合だけなので、
                // 通常はほとんど実行されない
                if self.bytes[left..right] == target.bytes[..] {
                    return Some(left);
                }
            }
        }

        return None;
    } // end of method

    /// selfの文字列にtargetが含まれているか判定する
    #[inline]
    pub fn contains_hash(&self, target: &RollingHash) -> bool {
        return self.find(target).is_some();
    } // end of method

    /// selfの文字列からtargetと一致する位置をすべて探す
    #[inline]
    pub fn find_all(&self, target: &RollingHash) -> Vec<usize> {
        // 同じ個数の底を使用している必要がある
        debug_assert_eq!(self.random_num, target.random_num);

        // 空文字列はすべての境界に存在する
        if target.n == 0 {
            return (0..=self.n).collect();
        }
        if target.n > self.n {
            return Vec::new();
        }

        let target_len = target.n;
        let mut result = Vec::<usize>::new();

        // Sの長さtarget_lenの区間を1文字ずつずらして調べる
        for left in 0..=(self.n - target_len) {
            let right = left + target_len;
            let mut matched = true;

            for hash_index in 0..self.random_num {
                // S[left..right]のハッシュ値をO(1)で取得する
                let removed = Self::mul_mod(self.hash[hash_index][left], self.bases[hash_index][target_len]);

                let substring_hash = Self::sub_mod(self.hash[hash_index][right], removed);

                // T全体のハッシュ値は事前計算済み
                let target_hash = target.hash[hash_index][target_len];

                if substring_hash != target_hash {
                    matched = false;
                    break;
                }
            }

            if matched {
                // ハッシュ衝突を完全に排除するための実データ比較
                if self.bytes[left..right] == target.bytes[..] {
                    result.push(left);
                }
            }
        }

        return result;
    } // end of method

    #[inline(always)]
    fn make_base(rng: &mut SplitMix64) -> u64 {
        let min_base = 257_u64;
        return min_base + (rng.next_u64() % (Self::MOD - min_base));
    } // end of method

    #[inline(always)]
    fn mul_mod(a: u64, b: u64) -> u64 {
        // return (((a as u128) * (b as u128)) % (Self::MOD as u128)) as u64;

        // 2^61 - 1 専用の高速化
        let x = (a as u128) * (b as u128);
        let modulo = Self::MOD as u128;

        // 2^61 - 1の性質で上位ビットを下位に畳み込み
        let mut value = (x & modulo) + (x >> 61);
        value = (value & modulo) + (value >> 61);

        let mut result = value as u64;
        if result >= Self::MOD {
            result -= Self::MOD;
        }
        return result;
    } // end of method

    #[inline(always)]
    fn add_mod(a: u64, b: u64) -> u64 {
        let mut value = a + b;
        if value >= Self::MOD {
            value -= Self::MOD;
        }
        return value;
    } // end of method

    #[inline(always)]
    fn sub_mod(a: u64, b: u64) -> u64 {
        if a >= b {
            return a - b;
        }
        return a + Self::MOD - b;
    } // end of method
} // end of impl RollingHash
